// 세 소스를 한 아이템으로 취합. 각 소스는 onError=continue 이므로 방어적으로 접근.
let weatherSummary = '날씨 정보를 가져오지 못했습니다.';
try {
  const w = $('날씨 조회').first().json;
  const cur = w.current || {};
  const daily = w.daily || {};
  const wmo = {0:'맑음',1:'대체로 맑음',2:'부분적으로 흐림',3:'흐림',45:'안개',48:'상고대 안개',51:'약한 이슬비',53:'이슬비',55:'강한 이슬비',61:'약한 비',63:'비',65:'강한 비',66:'어는 비',67:'강한 어는 비',71:'약한 눈',73:'눈',75:'강한 눈',77:'싸락눈',80:'약한 소나기',81:'소나기',82:'강한 소나기',85:'약한 눈소나기',86:'강한 눈소나기',95:'뇌우',96:'우박 동반 뇌우',99:'강한 우박 동반 뇌우'};
  if (cur.temperature_2m !== undefined) {
    weatherSummary = [
      `현재 ${cur.temperature_2m}°C (체감 ${cur.apparent_temperature}°C), ${wmo[cur.weather_code] || '정보없음'}`,
      `습도 ${cur.relative_humidity_2m}%, 바람 ${cur.wind_speed_10m}m/s`,
      `오늘 최고 ${daily.temperature_2m_max && daily.temperature_2m_max[0]}°C / 최저 ${daily.temperature_2m_min && daily.temperature_2m_min[0]}°C, 강수확률 ${daily.precipitation_probability_max && daily.precipitation_probability_max[0]}%`
    ].join('\n');
  }
} catch (e) { weatherSummary = `날씨 파싱 오류: ${e.message}`; }

let fxSummary = '환율 정보를 가져오지 못했습니다.';
try {
  const fx = $('환율 조회').first().json;
  const krw = fx && fx.rates ? fx.rates.KRW : null;
  if (krw) fxSummary = `1 USD = ${Number(krw).toLocaleString('ko-KR')} KRW (기준: ${fx.time_last_update_utc || ''})`;
} catch (e) { fxSummary = `환율 파싱 오류: ${e.message}`; }

let headlines = [];
try {
  const raw = $('뉴스 RSS 조회').first().json;
  const rssText = typeof raw === 'string' ? raw : (raw && (raw.data || raw.body) ) || '';
  const blocks = String(rssText).split('<item>').slice(1);
  headlines = blocks.slice(0, 5).map((b, i) => {
    const m = b.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
    let t = m ? m[1].trim() : '(제목 없음)';
    t = t.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
    return `${i + 1}. ${t}`;
  });
} catch (e) { headlines = [`뉴스 파싱 오류: ${e.message}`]; }
if (headlines.length === 0) headlines = ['뉴스 헤드라인을 가져오지 못했습니다.'];

const today = DateTime.now().setZone('Asia/Seoul').setLocale('ko').toFormat('yyyy년 M월 d일 (EEE)');

const briefInput = `[날짜] ${today}\n\n[서울 날씨]\n${weatherSummary}\n\n[환율]\n${fxSummary}\n\n[주요 뉴스 헤드라인]\n${headlines.join('\n')}`;

return [{ json: { briefInput, today, weatherSummary, fxSummary, headlines } }];

